// === Tab: MMs ===
//mariana magalhães — DSG1413 — 2020.1

//array para o numero de particulas
Particle[]p = new Array(1000);

//array e variavel para sortear uma cor para cada circulo
let cores = [color(6, 150, 104), color(107, 221, 140), color(41, 140, 192), 
  color(163, 201, 254), color(174, 115, 251), color(179, 86, 145), color(251, 9, 152), 
  color(250, 175, 227), color(67, 114, 222), color(129, 244, 254), color(118, 138, 96), 
  color(191, 205, 142), color(192, 244, 66), color(202, 81, 0), color(251, 209, 39), color(168, 121, 98), 
  color(101, 241, 18), color(253, 44, 59), color(254, 183, 134), color(201, 34, 214)];
let randomCor = cores[int(random)(cores.length)];

function setup() {
  createCanvas(600, 600);

  //criando as particulas
  for (j=0; j<p.length; j++) {
    p[j] = new Particle(300, 300, color((j+2)*randomCor, 70));
  }
}

function draw() {
  background(0);
  noStroke();

  //desenhar e mover as particulas atraves das funções
  for (k=0; k<p.length; k++) {
    p[k].move();
    p[k].draw();
  }
}

//oq é a particula
class Particle {
  x, y;
  c;
  constructor(ix, iy, ic) {
    x=ix;
    y=iy;
    c=ic;
  }
  //como se move
  function move() {
    x+=random(-1, 1);
    y+=random(-1, 1);

    if (mousePressed==true) {
      x+=random(-5, 5);
      y+=random(-5, 5);
    }
  }
  //como é desenhada
  function draw() {
    fill(c);
    ellipse(x, y, 20, 20);
  }
}

function keyPressed() {
  if (key=='s') {
    saveFrame();
  }
}

